public int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int start = i;
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b == 0) {
            break;
        }
        if (b < 0x80) {
            sb.append((char) b);
            i++;
        } else {
            int count = 1;
            if ((b & 0xE0) == 0xC0) {
                count = 2;
            } else if ((b & 0xF0) == 0xE0) {
                count = 3;
            } else if ((b & 0xF8) == 0xF0) {
                count = 4;
            } else {
                sb.append((char) b);
                i++;
                continue;
            }

            int codePoint = b & (0xFF >> count);
            for (int j = 1; j < count; j++) {
                if (!bb.hasRemaining()) {
                    break;
                }
                int nextByte = bb.get() & 0xFF;
                if ((nextByte & 0xC0) != 0x80) {
                    break;
                }
                codePoint = (codePoint << 6) | (nextByte & 0x3F);
            }

            if (count == 2) {
                if (codePoint < 0x80) {
                    sb.append((char) codePoint);
                } else {
                    sb.append((char) codePoint);
                }
            } else if (count == 3) {
                if (codePoint < 0x1000) {
                    sb.append((char) codePoint);
                } else {
                    sb.append((char) codePoint);
                }
            } else if (count == 4) {
                if (codePoint < 0x10000) {
                    sb.append((char) codePoint);
                } else {
                    sb.append((char) codePoint);
                }
            } else {
                sb.append((char) b);
            }
            i += count;
        }
    }
    return i;
}
