    int start = i;
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 0x80) {
            sb.append((char) b);
            i++;
        } else {
            int len = 0;
            if ((b & 0xE0) == 0xC0) {
                len = 2;
            } else if ((b & 0xF0) == 0xE0) {
                len = 3;
            } else if ((b & 0xF8) == 0xF0) {
                len = 4;
            } else {
                sb.append((char) b);
                i++;
                continue;
            }

            int codepoint = b & (0x1F << (6 * (len - 1)));
            for (int j = 1; j < len; j++) {
                if (!bb.hasRemaining()) {
                    return start;
                }
                b = bb.get() & 0xFF;
                if ((b & 0xC0) != 0x80) {
                    sb.append((char) b);
                    i++;
                    return start;
                }
                codepoint |= (b & 0x3F) << (6 * (len - 1 - j));
            }

            if (len == 2 && codepoint < 0x80) {
                sb.append((char) b);
                i++;
                return start;
            } else if (len == 3 && codepoint < 0x1000) {
                sb.append((char) b);
                i++;
                return start;
            } else if (len == 4 && codepoint < 0x10000) {
                sb.append((char) b);
                i++;
                return start;
            }

            if (codepoint > 0xFFFF) {
                sb.append((char) ((0xD7C0 + (codepoint >> 10)) & 0xDFFF));
                sb.append((char) (0xDC00 + (codepoint & 0x3FF)));
            } else {
                sb.append((char) codepoint);
            }
            i += len;
        }
    }
    return start;
}
