 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node;
    }

    TreeNode<T> newParent = node.left;
    TreeNode<T> subtree = newParent.right;

    // Perform rotation
    newParent.right = node;
    node.left = subtree;

    // Update heights and subtree sizes
    node.updateHeightAndSubtreeSize();
    newParent.updateHeightAndSubtreeSize();

    // Update parent references
    if (subtree != null) {
        subtree.parent = node;
    }
    newParent.parent = node.parent;
    node.parent = newParent;

    // Update the parent's child reference
    if (newParent.parent != null) {
        if (newParent.parent.left == node) {
            newParent.parent.left = newParent;
        } else {
            newParent.parent.right = newParent;
        }
    } else {
        // node was the root
        virtualRoot = newParent;
    }

    return newParent;
}
