private int parseEndOfLine(String headerPart, int end) {
    if (end >= headerPart.length()) {
        return headerPart.length();
    }

    int index = end;
    if (index < headerPart.length() && headerPart.charAt(index) == '\r') {
        index++;
        if (index < headerPart.length() && headerPart.charAt(index) == '\n') {
            return index + 1;
        }
    } else if (index < headerPart.length() && headerPart.charAt(index) == '\n') {
        return index + 1;
    }

    while (index < headerPart.length()) {
        char c = headerPart.charAt(index);
        if (c == '\r') {
            if (index + 1 < headerPart.length() && headerPart.charAt(index + 1) == '\n') {
                return index + 2;
            }
            return index + 1;
        } else if (c == '\n') {
            return index + 1;
        }
        index++;
    }

    return index;
}
```

