import org.jgrapht.Graph;

import java.util.HashMap;
import java.util.Map;

public class IsomorphicGraphMapping<V, E> {

    private Map<V, V> forwardMapping;
    private Map<V, V> backwardMapping;
    private Graph<V, E> graph1;
    private Graph<V, E> graph2;

    public IsomorphicGraphMapping(Map<V, V> forwardMapping, Map<V, V> backwardMapping, Graph<V, E> graph1, Graph<V, E> graph2) {
        this.forwardMapping = forwardMapping;
        this.backwardMapping = backwardMapping;
        this.graph1 = graph1;
        this.graph2 = graph2;
    }

    public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
        Map<V, V> forwardMapping = new HashMap<>();
        Map<V, V> backwardMapping = new HashMap<>();

        for (V vertex : graph.vertexSet()) {
            forwardMapping.put(vertex, vertex);
            backwardMapping.put(vertex, vertex);
        }

        return new IsomorphicGraphMapping<>(forwardMapping, backwardMapping, graph, graph);
    }

    public V getVertexCorrespondence(V v, boolean forward) {
        if (forward) {
            return forwardMapping.get(v);
        } else {
            return backwardMapping.get(v);
        }
    }

    public Map<V, V> getForwardMapping() {
        return forwardMapping;
    }

    public Map<V, V> getBackwardMapping() {
        return backwardMapping;
    }

    public Graph<V, E> getMappingDomain() {
        return graph1;
    }

    public Graph<V, E> getMappingRange() {
        return graph2;
    }

    public boolean hasVertexCorrespondence(V v) {
        return forwardMapping.containsKey(v);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        IsomorphicGraphMapping<?, ?> that = (IsomorphicGraphMapping<?, ?>) o;
        return java.util.Objects.equals(forwardMapping, that.forwardMapping) &&
               java.util.Objects.equals(backwardMapping, that.backwardMapping) &&
               java.util.Objects.equals(graph1, that.graph1) &&
               java.util.Objects.equals(graph2, that.graph2);
    }

    @Override
    public int hashCode() {
        return java.util.Objects.hash(forwardMapping, backwardMapping, graph1, graph2);
    }

    @Override
    public String toString() {
        return "IsomorphicGraphMapping{" +
                "forwardMapping=" + forwardMapping +
                ", backwardMapping=" + backwardMapping +
                ", graph1=" + graph1 +
                ", graph2=" + graph2 +
                '}';
    }

    public boolean isValidIsomorphism() {
        if (graph1.vertexSet().size() != graph2.vertexSet().size()) {
            return false;
        }
        if (graph1.edgeSet().size() != graph2.edgeSet().size()) {
            return false;
        }
        for (V v : graph1.vertexSet()) {
            if (!forwardMapping.containsKey(v) || !backwardMapping.containsKey(forwardMapping.get(v))) {
                return false;
            }
        }
        return true;
    }

    public boolean isEqualMapping(GraphMapping<V, E> rel) {
        if (!(rel instanceof IsomorphicGraphMapping)) {
            return false;
        }
        IsomorphicGraphMapping<V, E> other = (IsomorphicGraphMapping<V, E>) rel;
        return this.forwardMapping.equals(other.forwardMapping) &&
               this.backwardMapping.equals(other.backwardMapping);
    }

    public IsomorphicGraphMapping<V, E> compose(IsomorphicGraphMapping<V, E> otherMapping) {
        Map<V, V> newForward = new HashMap<>();
        Map<V, V> newBackward = new HashMap<>();

        for (Map.Entry<V, V> entry : this.forwardMapping.entrySet()) {
            V v = entry.getKey();
            V mappedV = entry.getValue();
            V otherMappedV = otherMapping.getVertexCorrespondence(mappedV, true);
            newForward.put(v, otherMappedV);
            newBackward.put(otherMappedV, v);
        }

        return new IsomorphicGraphMapping<>(newForward, newBackward, this.graph1, otherMapping.graph2);
    }

    public boolean hasEdgeCorrespondence(E e) {
        V source = graph1.getEdgeSource(e);
        V target = graph1.getEdgeTarget(e);
        V mappedSource = forwardMapping.get(source);
        V mappedTarget = forwardMapping.get(target);

        if (mappedSource == null || mappedTarget == null) {
            return false;
        }

        return graph2.containsEdge(mappedSource, mappedTarget);
    }

    public E getEdgeCorrespondence(E e, boolean forward) {
        if (!hasEdgeCorrespondence(e)) {
            return null;
        }

        V source = graph1.getEdgeSource(e);
        V target = graph1.getEdgeTarget(e);
        V mappedSource = forwardMapping.get(source);
        V mappedTarget = forwardMapping.get(target);

        if (forward) {
            return graph2.getEdge(mappedSource, mappedTarget);
        } else {
            return graph1.getEdge(backwardMapping.get(mappedSource), backwardMapping.get(mappedTarget));
        }
    }
}
