public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    if (file.isDirectory()) {
        deleteDirectoryOnExit(file);
    } else {
        deleteOnExit(file);
    }
}

private static void deleteOnExit(File file) throws IOException {
    if (!file.exists()) {
        return;
    }

    file.deleteOnExit();
}

private static void deleteDirectoryOnExit(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }

    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectoryOnExit(file);
            } else {
                deleteOnExit(file);
            }
        }
    }

    file.deleteOnExit();
}
