    }

    File[] files = directory.listFiles();
    if (files != null) {
        for (File file : files) {
            if (file.isDirectory()) {
                deleteDirectoryOnExit(file);
            } else {
                deleteOnExit(file);
        }
    }

    deleteOnExit(directory);
}
