public int addType(String value) {
    if (value == null) {
        return -1;
    }

    // Check if the type already exists in the type table
    for (int i = 0; i < typeCount; i++) {
        if (typeTable[i] != null && typeTable[i].value != null && typeTable[i].value.equals(value)) {
            return i;
        }
    }

    // Type doesn't exist, add it
    if (typeTable == null) {
        typeTable = new Entry[10];
    } else if (typeCount >= typeTable.length) {
        Entry[] newTable = new Entry[typeTable.length * 2];
        System.arraycopy(typeTable, 0, newTable, 0, typeTable.length);
        typeTable = newTable;
    }

    Entry newEntry = new Entry(typeCount, 0, value, 0, 0);
    typeTable[typeCount] = newEntry;
    typeCount++;

    return typeCount - 1;
}
