public Map<String, Object> diffStructure(String tableName, Mappings mappings) {
    Map<String, Object> result = new HashMap<>();
    Map<String, Fields> structures = getMapping(tableName).getProperties();
    Map<String, Object> currentProperties = mappings.getProperties();

    if (structures == null || currentProperties == null) {
        return result;
    }

    for (Map.Entry<String, Fields> entry : structures.entrySet()) {
        String fieldName = entry.getKey();
        if (!currentProperties.containsKey(fieldName)) {
            result.put(fieldName, entry.getValue());
        }
    }

    return result;
}
