    if (CollectionUtils.isEmpty(timeRanges)) {
        return Collections.emptyList();
    }

    List<EBPFProfilingAnalyzeTimeRange> result = new ArrayList<>();
    for (EBPFProfilingAnalyzeTimeRange range : timeRanges) {
        long start = range.getStartTime();
        long end = range.getEndTime();

        if (end - start <= FETCH_DATA_DURATION) {
            result.add(range);
