public long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }

    String timeBucketStr = String.valueOf(timeBucket);
    if (timeBucketStr.length() < 8) {
        return timeBucket;
    }

    try {
        DateTimeFormatter formatter = DateTimeFormat.forPattern("yyyyMMdd");
        DateTime dateTime = formatter.parseDateTime(timeBucketStr);

        int day = dateTime.getDayOfMonth();
        int newDay = ((day - 1) / dayStep) * dayStep + 1;

        DateTime newDateTime = dateTime.withDayOfMonth(newDay);
        return Long.parseLong(newDateTime.toString("yyyyMMdd"));
    } catch (Exception e) {
        return timeBucket;
    }
}
