public long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    String bucketStr = String.valueOf(timeBucket);
    if (bucketStr.length() < 8) {
        throw new IllegalArgumentException("Invalid time bucket format: " + timeBucket);
    }

    try {
        DateTime dt = new DateTime(timeBucket);
        int dayOfYear = dt.getDayOfYear();
        int year = dt.getYear();

        int adjustedDay = ((dayOfYear - 1) / dayStep) * dayStep + 1;

        DateTime adjustedDate = new DateTime(year, 1, 1, 0, 0, 0, 0).plusDays(adjustedDay - 1);

        return Long.parseLong(TIME_BUCKET_FORMATTER.print(adjustedDate));
    } catch (Exception e) {
        throw new RuntimeException("Failed to compress time bucket: " + timeBucket, e);
    }
}
