public long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }

    String timeBucketStr = String.valueOf(timeBucket);
    if (timeBucketStr.length() < 8) {
        return timeBucket;
    }

    String datePart = timeBucketStr.substring(0, 8);
    String timePart = timeStr.length() > 8 ? timeBucketStr.substring(8) : "000000";

    DateTime dateTime = DateTime.parse(datePart, TIME_BUCKET_FORMATTER);
    DateTime compressedDateTime = compressDateTime(dateTime, dayStep);
    String compressedDate = compressedDateTime.toString(TIME_BUCKET_FORMATTER);

    return Long.parseLong(compressedDate + timePart);
}

private DateTime compressDateTime(DateTime dateTime, int dayStep) {
    if (dayStep <= 0) {
        return dateTime;
    }

    DateTime normalized = dateTime.withTime(0, 0, 0, 0);
    long daysSinceEpoch = normalized.getMillis() / (24 * 60 * 60 * 1000);
    long compressedDays = (daysSinceEpoch / dayStep) * dayStep;
    return new DateTime(compressedDays * 24 * 60 * 60 * 1000);
}
