public void appendDetail(StringBuffer buffer, String fieldName, int[] array, Boolean fullDetail) {
    if (array == null) {
        appendNullText(buffer, fieldName);
        return;
    }

    appendStart(buffer, array);

    if (isFullDetail(fullDetail)) {
        appendArrayContent(buffer, array);
    } else {
        appendSummarySize(buffer, fieldName, array.length);
    }

    appendEnd(buffer, array);
}

private void appendArrayContent(StringBuffer buffer, int[] array) {
    buffer.append(arrayStart);
    for (int i = 0; i < array.length; i++) {
