/**
 * <p>Check if a String ends with a specified suffix (optionally case insensitive).</p>
 * @see String#endsWith(String)
 * @param str  the String to check, may be null
 * @param suffix the suffix to find, may be null
 * @param ignoreCase inidicates whether the compare should ignore case(case insensitive) or not.
 * @return <code>true</code> if the String starts with the prefix orboth <code>null</code>
 */
public static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return (str == null && suffix == null);
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    int strOffset = str.length() - suffix.length();
    if (ignoreCase) {
        return str.substring(strOffset).equalsIgnoreCase(suffix);
    } else {
        return str.substring(strOffset).equals(suffix);
    }
}
