public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }

    // Remove leading slash if present for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    if (path.isEmpty()) {
        return new ArrayList<>();
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    decodePathSegment(segments, path, decode);

    return segments;
}

private void decodePathSegment(List<PathSegmentImpl> segments, String path, boolean decode) {
    if (path == null || path.isEmpty()) {
        return;
    }

    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }

        Map<String, String> matrixParameters = decodeMatrix(part, decode);
        String segmentPath = part.contains(";") ? part.substring(0, part.indexOf(';')) : part;

        segments.add(new PathSegmentImpl(segmentPath, decode, matrixParameters));
    }
}

private Map<String, String> decodeMatrix(String pathSegment, boolean decode) {
    if (!pathSegment.contains(";")) {
        return new HashMap<>();
    }

    String matrixPart = pathSegment.substring(pathSegment.indexOf(';') + 1);
    String segmentPath = pathSegment.substring(0, pathSegment.indexOf(';'));

    Map<String, String> params = new HashMap<>();
    String[] matrixParams = matrixPart.split(";");

    for (String param : matrixParams) {
        if (param.isEmpty()) {
            continue;
        }

        if (param.contains("=")) {
            String key = param.substring(0, param.indexOf('='));
            String value = param.substring(param.indexOf('=') + 1);
            if (decode) {
                key = decode(key, 0);
                value = decode(value, 0);
            }
            params.put(key, value);
        } else {
            if (decode) {
                params.put(decode(param, 0), "");
            } else {
                params.put(param, "");
            }
        }
    }

    return params;
}

private String decode(String s, int n) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '%' && i + 2 < s.length()) {
            String hex = s.substring(i + 1, i + 3);
            try {
                int octet = Integer.parseInt(hex, 16);
                sb.append((char) octet);
                i += 2;
            } catch (NumberFormatException e) {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}
