public List<String> decodePath(URI u, boolean decode) {
    if (u == null) {
        return new ArrayList<>();
    }

    String path = u.getPath();
    if (path == null) {
        return new ArrayList<>();
    }

    if (path.isEmpty()) {
        return new ArrayList<>();
    }

    List<String> segments = new ArrayList<>();
    int start = 0;
    int len = path.length();

    // Skip leading slash if present
    if (path.charAt(0) == '/') {
        start = 1;
    }

    while (start < len) {
        int end = path.indexOf('/', start);
        if (end == -1) {
            end = len;
        }

        if (end > start) {
            String segment = path.substring(start, end);
            if (decode) {
                try {
                    segment = java.net.URLDecoder.decode(segment, "UTF-8");
                } catch (Exception e) {
                    // Ignore and use original segment
                }
            }
            segments.add(segment);
        }

        start = end + 1;
    }

    return segments;
}
