/**
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
void pop(String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    char firstChar = descriptor.charAt(0);
    if (firstChar == '(') {
        // Method descriptor: pop all argument types
        int i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            int offset = i;
            while (offset < descriptor.length() && (descriptor.charAt(offset) == '[' || descriptor.charAt(offset) == 'L')) {
                if (descriptor.charAt(offset) == 'L') {
                    while (offset < descriptor.length() && descriptor.charAt(offset) != ';') {
                        offset++;
                    }
                    if (offset < descriptor.length()) {
                        offset++;
                    }
                } else {
                    offset++;
                }
            }
            String paramDescriptor = descriptor.substring(i, offset);
            pop(paramDescriptor);
            i = offset;
        }
        if (i < descriptor.length() && descriptor.charAt(i) == ')') {
            i++;
            // Skip return type if present
            if (i < descriptor.length()) {
                char returnType = descriptor.charAt(i);
                if (returnType == 'V') {
                    // Void return - do nothing
                } else if (returnType == 'D' || returnType == 'J') {
                    pop(2);
                } else {
                    pop(1);
                }
            }
        }
    } else {
        // Field descriptor: pop one value (or two for long/double)
        if (firstChar == 'D' || firstChar == 'J') {
            pop(2);
        } else {
            pop(1);
        }
    }
}
