/**
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
void pop(String descriptor) {
    int offset = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: skip the opening '(' and parse until the closing ')'
        offset = 1;
        while (offset < descriptor.length() && descriptor.charAt(offset) != ')') {
            offset += getDescriptorSize(descriptor, offset);
        }
        // Skip the closing ')' and the return type
        if (offset < descriptor.length()) {
            offset++;
            while (offset < descriptor.length() && descriptor.charAt(offset) != ')') {
                offset++;
            }
        }
    }
    // Parse the type(s) and pop them
    while (offset < descriptor.length()) {
        int size = getDescriptorSize(descriptor, offset);
        pop(size);
        offset += size;
    }
}

private int getDescriptorSize(String descriptor, int offset) {
    char c = descriptor.charAt(offset);
    switch (c) {
        case 'Z':
        case 'B':
        case 'C':
        case 'S':
        case 'I':
        case 'F':
        case 'J':
        case 'D':
        case 'L':
        case '[':
            if (c == 'J' || c == 'D') {
                return 2;
            } else if (c == 'L' || c == '[') {
                int end = offset;
                if (c == 'L') {
                    end = descriptor.indexOf(';', offset);
                } else {
                    while (end < descriptor.length() && descriptor.charAt(end) == '[') {
                        end++;
                    }
                    if (end < descriptor.length() && descriptor.charAt(end) == 'L') {
                        end = descriptor.indexOf(';', end);
                    }
                }
                return end - offset + 1;
            } else {
                return 1;
            }
        default:
            return 1;
    }
}
