public boolean containsAllFields(Fields fields) {
    if (fields == null || properties == null) {
        return false;
    }

    Map<String, Object> propertiesMap = properties;
    Map<String, Object> fieldsMap = fields.getFields();

    if (fieldsMap == null) {
        return true;
    }

    for (Map.Entry<String, Object> entry : fieldsMap.entrySet()) {
        String fieldName = entry.getKey();
        Object fieldValue = entry.getValue();

        if (!propertiesMap.containsKey(fieldName)) {
            return false;
        }

        Object propertyValue = propertiesMap.get(fieldName);

        if (fieldValue instanceof Map && propertyValue instanceof Map) {
            if (!containsAllFieldsRecursive((Map<String, Object>) fieldValue, (Map<String, Object>) propertyValue)) {
                return false;
            }
        } else if (!Objects.equals(fieldValue, propertyValue)) {
            return false;
        }
    }

    return true;
}

