public class CharacterConverter implements Converter {
    private Object defaultValue;

    public CharacterConverter() {
        this.defaultValue = null;
    }

    public CharacterConverter(Object defaultValue) {
        this.defaultValue = defaultValue;
    }

    public Object getDefaultType() {
        return defaultValue;
    }

    public Object convert(Class type, Object value) throws Exception {
        return convertToType(type, value);
    }

    /**
     * <p>Convert the input object into a java.lang.Character.</p>
     * @param type Data type to which this value should be converted.
     * @param value The input value to be converted.
     * @return The converted value.
     * @throws Exception if conversion cannot be performed successfully
     * @since 1.8.0
     */
    public Object convertToType(Class type, Object value) throws Exception {
        if (value == null) {
            return defaultValue;
        }

        String valueStr = value.toString();
        if (valueStr.length() == 0) {
            return defaultValue;
        }

        return Character.valueOf(valueStr.charAt(0));
    }

    public String convertToString(Object value) {
        if (value == null) {
            return "";
        }
        if (value instanceof Character) {
            return value.toString();
        }
        return value.toString();
    }
}
