import java.lang.reflect.Array;

public class ArrayUtils {

    public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
        if (array == null) {
            return Array.newInstance(newArrayComponentType, 1);
        }

        int length = Array.getLength(array);
        Class<?> componentType = array.getClass().getComponentType();
        Object newArray = Array.newInstance(componentType, length + 1);
        System.arraycopy(array, 0, newArray, 0, length);
        // Set the last element to the default value for the component type
        Object defaultValue = getDefaultValue(componentType);
        Array.set(newArray, length, defaultValue);
        return newArray;
    }

    private static Object getDefaultValue(Class<?> type) {
        if (type == int.class) return 0;
        if (type == boolean.class) return false;
        if (type == char.class) return '\0';
        if (type == byte.class) return 0;
        if (type == short.class) return 0;
        if (type == long.class) 0L;
        if (type == float.class) 0.0f;
        if (type == double.class) 0.0;
        return null;
    }
}
