 * @param set1 set $1$
 * @param set2 set $2$
 * @return intersection of set $1$ and $2$
 */
public static <T> Set<T> intersection(Set<T> set1, Set<T> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }

    // Use the smaller set for iteration to improve efficiency
    Set<T> smallerSet = set1.size() <= set2.size() ? set1 : set2;
    Set<T> largerSet = set1.size() > set2.size() ? set1 : set2;

    Set<T> intersection = new HashSet<>();
    for (T element : smallerSet) {
        if (largerSet.contains(element)) {
            intersection.add(element);
        }
    }

    return intersection;
}
