public int removeUnusedNodes() {
    int removedCount = 0;
    if (_categoryModel != null) {
        CategoryNode root = _categoryModel.getRoot();
        if (root != null) {
            removedCount = removeUnusedNodesRecursive(root);
            _categoryModel.reload();
        }
    }
    return removedCount;
}

private int removeUnusedNodesRecursive(CategoryNode node) {
    int removedCount = 0;

    // Process children first (post-order traversal)
    for (int i = node.getChildCount() - 1; i >= 0; i--) {
        CategoryNode child = (CategoryNode) node.getChildAt(i);
        removedCount += removeUnusedNodesRecursive(child);
    }

    // Check if current node should be removed
    if (node != _categoryModel.getRoot() && !node.isActive()) {
        // Check if node has no active descendants
        if (node.getChildCount() == 0) {
            _categoryModel.removeNodeFromParent(node);
            removedCount++;
        }
    }

    return removedCount;
}
