public int removeUnusedNodes() {
    int removedCount = 0;
    if (_tree == null || _categoryModel == null) {
        return 0;
    }

    // Get the root node of the tree
    CategoryNode root = _categoryModel.getRoot();
    if (root == null) {
        return 0;
    }

    // Collect all nodes that are used (selected or ancestors of selected nodes)
    java.util.HashSet<CategoryNode> usedNodes = new java.util.HashSet<CategoryNode>();

    // Add all selected nodes and their ancestors
    for (CategoryNode node : _categoryModel.getSelectedNodes()) {
        CategoryNode current = node;
        while (current != null) {
            usedNodes.add(current);
            current = current.getParent();
        }
    }

    // Remove unused nodes from the tree
    removedCount = removeUnusedNodesRecursive(root, usedNodes);

    return removedCount;
}

private int removeUnusedNodesRecursive(CategoryNode node, java.util.HashSet<CategoryNode> usedNodes) {
    int removedCount = 0;

    // Iterate through children in reverse order to safely remove
    for (int i = node.getChildCount() - 1; i >= 0; i--) {
