public static String trimLeadingWhitespace(String str) {
    if (!hasLength(str)) {
        return str;
    }

    int start = 0;
    int len = str.length();

    for (int i = 0; i < len; i++) {
        if (!Character.isWhitespace(str.charAt(i))) {
            break;
        }
        start++;
    }

    return (start == len) ? "" : str.substring(start);
}
