public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    int utfOffset = cpInfoOffsets[constantPoolEntryIndex];
    int utfLength = classFileBuffer[utfOffset + 1] & 0xFF;
    utfLength = (utfLength << 8) | (classFileBuffer[utfOffset + 2] & 0xFF);
    int utfStart = utfOffset + 3;
    int count = 0;
    for (int i = 0; i < utfLength; i++) {
        int byte1 = classFileBuffer[utfStart + i] & 0xFF;
        if (byte1 < 0x80) {
            charBuffer[count++] = (char) byte1;
        } else if (byte1 < 0xE0) {
            int byte2 = classFileBuffer[utfStart + ++i] & 0xFF;
            charBuffer[count++] = (char) ((byte1 & 0x1F) << 6 | (byte2 & 0x3F));
        } else {
            int byte2 = classFileBuffer[utfStart + ++i] & 0xFF;
            int byte3 = classFileBuffer[utfStart + ++i] & 0xFF;
            charBuffer[count++] = (char) ((byte1 & 0x0F) << 12 | (byte2 & 0x3F) << 6 | (byte3 & 0x3F);
        }
    }
    return new String(charBuffer, 0, count);
}
