/**
 * Either finds and returns a circulator to the node on the boundary of the component, which satisfies the  {@code predicate} or returns a circulator to the {@code stop} node.
 * @param predicate the condition the desired node should satisfy
 * @param start the node to start the search from
 * @param stop the node to end the search with
 * @param dir the direction to start the traversal in
 * @return a circulator to the node satisfying the {@code predicate} or to the {@code stop} node
 */
public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, null);

    // Traverse the outer face starting from 'start' in direction 'dir'
    // until we find a node satisfying the predicate or reach 'stop'
    Node current = start;
    Node prev = null;

    // Handle first node separately to avoid infinite loop
    if (predicate.test(current)) {
        return new OuterFaceCirculator(current, prev);
    }

    if (current.equals(stop)) {
        return new OuterFaceCirculator(current, prev);
    }

    // Continue traversal
    do {
        // Get next node on outer face in specified direction
        Node next = current.nextOnOuterFace(prev);
        if (next == null) {
            break;
        }

        prev = current;
        current = next;

        // Check if current node satisfies predicate
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, prev);
        }

        // Check if we reached the stop node
        if (current.equals(stop)) {
            return new OuterFaceCirculator(current, prev);
        }
    } while (true);

    // If we haven't found anything, return circulator to stop node
    return new OuterFaceCirculator(stop, prev);
}
```

