public class Strings {

    /**
     * Delete any character in a given String.
     * @param inString the original String
     * @param charsToDelete a set of characters to delete.E.g. "az\n" will delete 'a's, 'z's and new lines.
     * @return the resulting String
     */
    public static String deleteAny(String inString, String charsToDelete) {
        if (inString == null || charsToDelete == null) {
            return inString;
        }

        StringBuilder result = new StringBuilder();
        int inStringLen = inString.length();
        int deleteCharsLen = charsToDelete.length();

        // Create a boolean array to mark characters to delete
        boolean[] deleteMask = new boolean[65536]; // For all possible char values
        for (int i = 0; i < deleteCharsLen; i++) {
            char c = charsToDelete.charAt(i);
            deleteMask[c] = true;
        }

        for (int i = 0; i < inStringLen; i++) {
            char c = inString.charAt(i);
            if (!deleteMask[c]) {
                result.append(c);
            }
        }

        return result.toString();
    }
}
```

