public class UriPattern {
    private Pattern regexPattern;
    private int[] groupIndexes;

    public UriPattern() {
        this.regexPattern = null;
        this.groupIndexes = null;
    }

    public UriPattern(String regex) {
        this.regexPattern = Pattern.compile(regex);
        this.groupIndexes = null;
    }

    public UriPattern(String regex, int[] groupIndexes) {
        this.regexPattern = Pattern.compile(regex);
        this.groupIndexes = groupIndexes;
    }

    public UriPattern(Pattern regexPattern) {
        this.regexPattern = regexPattern;
        this.groupIndexes = null;
    }

    public UriPattern(Pattern regexPattern, int[] groupIndexes) {
        this.regexPattern = regexPattern;
        this.groupIndexes = groupIndexes;
    }

    public String getRegex() {
        if (regexPattern == null) {
            return null;
        }
        return regexPattern.pattern();
    }

    public int[] getGroupIndexes() {
        return groupIndexes;
    }

    public UriPattern compile(String regex) {
        return new UriPattern(regex);
    }

    public MatchResult match(CharSequence uri, List<String> groupValues) {
        if (regexPattern == null) {
            return null;
        }
        Matcher matcher = regexPattern.matcher(uri);
        if (matcher.matches()) {
            return new GroupIndexMatchResult(matcher);
        }
        return null;
    }

