        if (regexPattern == null) {
            return null;
        }
        Matcher matcher = regexPattern.matcher(uri);
        if (matcher.matches()) {
            return new GroupIndexMatchResult(matcher);
        }
        return null;
    }

    private class GroupIndexMatchResult implements MatchResult {
        private MatchResult result;

        public GroupIndexMatchResult(MatchResult result) {
            this.result = result;
        }

        @Override
        public int start() {
            return result.start();
        }

        @Override
        public int start(int group) {
            return result.start(group);
        }

        @Override
        public int end() {
