public static <V, E> List<V> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    // Build adjacency map from edge set
    Map<V, List<V>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(target);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(source);
    }

    // Find starting vertex (any vertex with at least one neighbor)
    V startVertex = null;
    for (V vertex : adjacency.keySet()) {
        startVertex = vertex;
        break;
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Cannot determine start vertex from empty adjacency map");
    }

    // Hierholzer's algorithm to find Eulerian circuit
    Deque<V> circuit = new ArrayDeque<>();
    Deque<V> stack = new ArrayDeque<>();
    stack.push(startVertex);

    Map<V, Iterator<V>> neighborsIterator = new HashMap<>();
    for (V vertex : adjacency.keySet()) {
        neighborsIterator.put(vertex, adjacency.get(vertex).iterator());
    }

    while (!stack.isEmpty()) {
        V current = stack.peek();
        if (adjacency.get(current) != null && !adjacency.get(current).isEmpty()) {
            // Get next neighbor
            V next = adjacency.get(current).remove(adjacency.get(current).size() - 1);
            // Remove the reverse edge
            if (adjacency.get(next) != null) {
                adjacency.get(next).remove(current);
            }
            stack.push(next);
        } else {
            circuit.push(stack.pop());
        }
    }

    // Convert circuit to list (excluding the last duplicate vertex)
    List<V> result = new ArrayList<>();
    while (!circuit.isEmpty()) {
        result.add(circuit.pop());
    }

    return result;
}
```

