        if (neighborsIterator.containsKey(current) && neighborsIterator.get(current).hasNext()) {
            V next = neighborsIterator.get(current).next();
            stack.push(next);
        } else {
            circuit.push(stack.pop());
        }
    }

    // Convert circuit to list (excluding the last element which duplicates the first)
    List<V> result = new ArrayList<>();
    Iterator<V> it = circuit.iterator();
    if (it.hasNext()) {
        it.next(); // Skip first element (will be same as last)
    }
    while (it.hasNext()) {
        result.add(it.next());
    }

    return result;
