            adj.get(v).remove((Integer) next);
            adj.get(next).remove((Integer) v);
        } else {
            circuit.add(stack.pop());
        }
    }

    Collections.reverse(circuit);

    // Convert to list of vertices
    List<Integer> result = new ArrayList<>();
    for (int v : circuit) {
        result.add(v);
    }

    return result;
