    constantPool.putByte(Symbol.CONSTANT_NAME_AND_TYPE);
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);
    constantPool.putShort(nameIndex).putShort(descriptorIndex);
