public boolean isCompatible(List<Bucket> existingBuckets, List<Bucket> currentBuckets) {
    if (existingBuckets == null || currentBuckets == null) {
        return existingBuckets == currentBuckets;
    }
    if (existingBuckets.size() != currentBuckets.size()) {
        return false;
    }
    for (int i = 0; i < existingBuckets.size(); i++) {
        Bucket existingBucket = existingBuckets.get(i);
        Bucket currentBucket = currentBuckets.get(i);
        if (existingBucket == null && currentBucket != null) {
            return false;
        }
        if (existingBucket != null && currentBucket == null) {
            return false;
        }
        if (existingBucket != null && currentBucket != null) {
            if (existingBucket.getMin() != currentBucket.getMin() || 
                existingBucket.getMax() != currentBucket.getMax()) {
                return false;
        }
    }
    return true;
}
