void addLineNumber(int lineNumber) {
    if (this.lineNumber == 0) {
        this.lineNumber = (short) lineNumber;
    } else {
        if (otherLineNumbers == null) {
            otherLineNumbers = new int[LINE_NUMBERS_CAPACITY_INCREMENT];
            otherLineNumbers[0] = this.lineNumber & 0xFFFF;
            otherLineNumbers[1] = lineNumber;
            this.lineNumber = (short) (otherLineNumbers.length >> 16);
        } else {
            int length = (this.lineNumber & 0xFFFF) >> 16;
            if (length >= otherLineNumbers.length) {
                int[] newLineNumbers = new int[otherLineNumbers.length + LINE_NUMBERS_CAPACITY_INCREMENT];
                System.arraycopy(otherLineNumbers, 0, newLineNumbers, 0, otherLineNumbers.length);
                otherLineNumbers = newLineNumbers;
            }
            otherLineNumbers[length] = lineNumber;
            this.lineNumber = (short) (((length + 1) << 16) | (this.lineNumber & 0xFFFF));
        }
    }
}
