void addLineNumber(int lineNumber) {
    if (this.lineNumber == 0) {
        this.lineNumber = (short) lineNumber;
    } else {
        if (otherLineNumbers == null) {
            otherLineNumbers = new int[LINE_NUMBERS_CAPACITY_INCREMENT];
            otherLineNumbers[0] = this.lineNumber & 0xFFFF;
            otherLineNumbers[1] = lineNumber;
            this.lineNumber = (short) (1 | (1 << 15));
        } else {
            int length = otherLineNumbers.length;
            int count = otherLineNumbers[0] & 0xFFFF;
            if (count + 1 > length) {
