/**
 * Remove the non null {@code node} from the list.
 */
boolean unlink(ListNodeImpl node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl prev = node.prev;
    ListNodeImpl next = node.next;

    if (prev == null && next == null) {
        // Node is the only node in the list
        if (head == node) {
            head = null;
            last = null;
            size = 0;
            return true;
        } else {
            return false;
        }
    }

    // Update previous node's next pointer
    if (prev != null) {
        prev.next = next;
    } else {
        // Node is the head
        head = next;
    }

    // Update next node's previous pointer
    if (next != null) {
        next.prev = prev;
    } else {
        // Node is the last node
        last = prev;
    }

    // Clear the node's pointers
    node.prev = null;
    node.next = null;

    size--;
    return true;
}
