public String trimLeadingCharacter(String str, char leadingCharacter) {
    if (str == null) {
        return null;
    }

    int start = 0;
    int len = str.length();

    while (start < len && str.charAt(start) == leadingCharacter) {
        start++;
    }

    if (start == len) {
        return "";
    }

    return str.substring(start);
}
```

