public Pair<List<Integer>, Integer> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0);
    }

    int totalSum = 0;
    for (int bound : bounds) {
        totalSum += bound;
    }

    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    int suffixSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffixSums.add(suffixSum);
    }

    Collections.reverse(suffixSums);

    return Pair.of(suffixSums, totalSum);
}
```

