public void moveAllListNodes(DoublyLinkedList<V> list) {
    if (list == null || list.isEmpty()) {
        return;
    }

    ListNodeImpl<V> current = list.head;
    while (current != null) {
        ListNodeImpl<V> nextNode = current.next;

        // Remove from current list
        if (current.prev != null) {
            current.prev.next = current.next;
        } else {
            list.head = current.next;
        }

        if (current.next != null) {
            current.next.prev = current.prev;
        } else {
            list.last = current.prev;
        }

        // Reset pointers
        current.prev = null;
        current.next = null;

        // Add to this list
        addListNode(current);

        current = nextNode;
    }

    list.size = 0;
    list.nextIndex = 0;
}
```

