public void moveAllListNodes(DoublyLinkedList<V> list) {
    if (list == null || list.isEmpty()) {
        return;
    }

    ListNodeImpl<V> node = list.head;
    while (node != null) {
        ListNodeImpl<V> nextNode = node.next;

        // Remove from original list
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            list.head = node.next;
        }

        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            list.last = node.prev;
        }

        list.size--;
        list.nextIndex--;

        // Add to this list
        node.prev = last;
        node.next = null;

        if (last != null) {
            last.next = node;
        } else {
            head = node;
        }

        last = node;
        size++;

        node = nextNode;
    }

    list.clear();
}
