    if (map == null) {
        return;
    }

    Map<String, Method> mapWriteMethods = map.getWriteMethods();
    Map<String, Method> mapReadMethods = map.getReadMethods();

    if (mapWriteMethods != null) {
        for (Map.Entry<String, Method> entry : mapWriteMethods.entrySet()) {
            String key = entry.getKey();
            Method writeMethod = entry.getValue();

            // Only put if there's a corresponding readable method (read-write property)
            if (mapReadMethods != null && mapReadMethods.containsKey(key)) {
                try {
                    Method readMethod = map.getReadMethod(key);
                    if (readMethod != null) {
                        Object value = readMethod.invoke(map.getBean(), NULL_ARGUMENTS);
                        this.put(key, value);
                    }
                } catch (Exception e) {
                    // Skip this property due to access issues
                }
            }
        }
    }
}
