import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class Base64Decoder {

    private static final String Base64Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";

    /**
     * Decoding a string to a string follow the Base64 regular.
     */
    public static String base64Decode(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        byte[] decodedBytes = base64DecodeToArray(s);
        return new String(decodedBytes, StandardCharsets.UTF_8);
    }

    /**
     * Decodes a Base64 encoded string to a byte array.
     */
    public static byte[] base64DecodeToArray(String s) {
        if (s == null || s.isEmpty()) {
            return new byte[0];
        }

        // Remove any whitespace
        s = s.trim();

        // Check for valid Base64 characters
        if (!s.matches("[" + Base64Chars + "]*")) {
            return new byte[0];
        }

        int sLen = s.length();
        int numPadBytes = 0;

        // Count padding characters
        for (int i = sLen - 1; i >= 0; i--) {
            if (s.charAt(i) == '=') {
                numPadBytes++;
            } else {
                break;
            }
        }

        int numQuads = (sLen / 4);
        int numBytes = numQuads * 3 - numPadBytes;

        byte[] result = new byte[numBytes];
        int resultIndex = 0;

        for (int i = 0; i < numQuads; i++) {
            int b1 = Base64Chars.indexOf(s.charAt(i * 4));
            int b2 = Base64Chars.indexOf(s.charAt(i * 4 + 1));
            int b3 = Base64Chars.indexOf(s.charAt(i * 4 + 2));
            int b4 = Base64Chars.indexOf(s.charAt(i * 4 + 3));

            int triple = (b1 << 18) | (b2 << 12) | (b3 << 6) | b4;

            if (i == numQuads - 1) {
                // Last quad might have padding
                if (numPadBytes == 0) {
                    result[resultIndex++] = (byte) ((triple >> 16) & 0xff);
                    result[resultIndex++] = (byte) ((triple >> 8) & 0xff);
                    result[resultIndex++] = (byte) (triple & 0xff);
                } else if (numPadBytes == 1) {
                    result[resultIndex++] = (byte) ((triple >> 16) & 0xff);
                    result[resultIndex++] = (byte) ((triple >> 8) & 0xff);
                } else {
                    result[resultIndex++] = (byte) ((triple >> 16) & 0xff);
                }
            } else {
                result[resultIndex++] = (byte) ((triple >> 16) & 0xff);
                result[resultIndex++] = (byte) ((triple >> 8) & 0xff);
                result[resultIndex++] = (byte) (triple & 0xff);
            }
        }

        return result;
    }
}
```

