/**
 * Computes the global separator list of the  {@code graph}. More precisely, for every edge $e$ in the $G = (V, E)$ computes list of minimal separators $S_e$ in the neighborhood of $e$ and then concatenates these lists. Note: the result may contain duplicates
 * @return the list of minimal separators of every edge $e$ in the inspected graph
 */
public List<List<V>> computeGlobalSeparatorList() {
    List<List<V>> globalSeparatorList = new ArrayList<>();

    for (E edge : graph.edgeSet()) {
        // Skip self-loops if any (edges connecting a vertex to itself)
        if (graph.getEdgeSource(edge).equals(graph.getEdgeTarget(edge))) {
            continue;
        }

        // Get the neighborhood set of the edge
        Set<V> neighborhood = neighborhoodSetOf(graph, edge);

        // Create a subgraph induced by the neighborhood
        Graph<V, E> subgraph = new SimpleGraph<>(null, null, false);
        for (V v : neighborhood) {
            subgraph.addVertex(v);
        }
        for (V v1 : neighborhood) {
            for (V v2 : neighborhood) {
                if (v1 != v2 && graph.containsEdge(v1, v2)) {
                    subgraph.addEdge(v1, v2);
                }
            }
        }

        // Find minimal separators in the neighborhood subgraph
        List<List<V>> separators = findSeparators(subgraph, edge);

        // Add separators to global list
        globalSeparatorList.addAll(separators);
    }

    return globalSeparatorList;
}
```

