public void abbreviate(StringBuffer buf, int nameStart) {
    int start = nameStart;
    int count = 0;

    // Count the number of substrings separated by "."
    for (int i = nameStart; i < buf.length(); i++) {
        if (buf.charAt(i) == '.') {
            count++;
        }
    }

    // If count is greater than or equal to the number of substrings, clear everything
    if (count >= this.count) {
        buf.delete(nameStart, buf.length());
        return;
    }

    // Find the position after skipping 'count' substrings
    int skip = this.count;
    for (int i = nameStart; i < buf.length(); i++) {
        if (buf.charAt(i) == '.') {
            skip--;
            if (skip == 0) {
                start = i + 1;
                break;
            }
        }
    }

    // Append the ellipsis if needed
    if (this.ellipsis != 0) {
        buf.insert(nameStart, this.ellipsis);
        nameStart++;
    }

    // Move the remaining part to the beginning
    int length = buf.length() - start;
    for (int i = 0; i < length; i++) {
        buf.setCharAt(nameStart + i, buf.charAt(start + i));
    }

    // Delete the remaining part
    buf.setLength(nameStart + length);
}
