public boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices == null || graph == null) {
        return false;
    }

    // Check if all vertices exist in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
    }

    // For each pair of distinct vertices in the set, check if there is an edge between them
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2) {
                if (!graph.containsEdge(v1, v2)) {
                    return false;
                }
            }
        }
    }

    return true;
}
```

