/**
 * Pops as many abstract types from the output frame stack as described by the given descriptor.
 * @param descriptor a type or method descriptor (in which case its argument types are popped).
 */
void pop(String descriptor) {
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types
        int offset = 1;
        while (offset < descriptor.length() && descriptor.charAt(offset) != ')') {
            offset += pop(descriptor, offset);
        }
    } else {
        // Type descriptor: pop one value
        pop(descriptor, 0);
    }
}

private int pop(String descriptor, int offset) {
    char c = descriptor.charAt(offset);
    switch (c) {
        case 'Z':
        case 'B':
        case 'C':
        case 'S':
        case 'I':
        case 'F':
            push(ITEM_INTEGER);
            return 1;
        case 'J':
        case 'D':
            push(ITEM_LONG);
            push(ITEM_TOP);
            return 1;
        case 'L':
            int end = descriptor.indexOf(';', offset);
            if (end == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            push(ITEM_OBJECT);
            return end - offset + 1;
        case '[':
            int count = 1;
            while (offset + count < descriptor.length() && descriptor.charAt(offset + count) == '[') {
                count++;
            }
            if (offset + count < descriptor.length()) {
                char elementType = descriptor.charAt(offset + count);
                if (elementType == 'L') {
                    int end = descriptor.indexOf(';', offset + count);
                    if (end == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    push(ITEM_OBJECT);
                    return count + end - offset + 1;
                } else {
                    push(ITEM_OBJECT);
                    return count + 1;
                }
            } else {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}
