        case 'I':
        case 'F':
            pop(1);
            break;
        case 'J':
        case 'D':
            pop(2);
            break;
        case 'L':
            // Object type - count array dimensions
            int arrayDims = 0;
            int i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                arrayDims++;
                i++;
            }
            if (arrayDims > 0) {
                pop(arrayDims);
            } else {
                pop(1);
            }
            break;
        case '[':
            // Array type - count dimensions
            int dims = 0;
            for (int j = 0; j < descriptor.length(); j++) {
                if (descriptor.charAt(j) == '[') {
                    dims++;
                }
            }
            pop(dims + 1);
            break;
        case '(':
            // Method descriptor - pop arguments
            int args = 0;
            int parenEnd = descriptor.indexOf(')');
            if (parenEnd != -1) {
                String params = descriptor.substring(1, parenEnd);
                int j = 0;
                while (j < params.length()) {
