public String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            result.append("%7B");
        } else if (c == '}') {
            result.append("%7D");
        } else {
            result.append(c);
        }
    }
    return result.toString();
}
